mapper.select:
SELECT id,parent_user_id,student_id,class_organization_id,enabled_flag,version_no
FROM growth_rank_preference
WHERE parent_user_id=#{parentId} AND student_id=#{studentId} AND class_organization_id=#{classId}

mapper.update:
UPDATE growth_rank_preference SET enabled_flag=#{row.enabled},version_no=#{row.version},updated_at=CURRENT_TIMESTAMP
WHERE id=#{row.id} AND parent_user_id=#{row.parentId} AND student_id=#{row.studentId}
  AND class_organization_id=#{row.classId} AND version_no=#{expectedVersion}
